// Per-(L1, L2) launchers. Each explicit instantiation lives in its own
// translation unit (generated by CMake) so the unrolled kernels build in
// parallel.
#pragma once

#include <ATen/ATen.h>

#include <algorithm>
#include <limits>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>

#include "channelwise.cuh"

namespace molnex::equivariance {

struct ProductArgs {
  at::Tensor a, b, w;
  at::Tensor source;            // (E,) int64
  at::Tensor order, rowptr;     // CSR by target, int32
  at::Tensor out;               // (splits, rows_d, NK·U): one partial per CTA of a row
  at::ArrayRef<double> coefficients;
  int64_t channels;
  int64_t splits;
};

// Rows split over CTAs so a small system still fills the device; one for a
// system with more rows than a few CTAs per SM.
inline int64_t row_splits(int64_t rows) {
  const int64_t sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
  return std::clamp<int64_t>((4 * sms + rows - 1) / std::max<int64_t>(rows, 1), 1, 8);
}

struct AdjointArgs {
  at::Tensor a, b, w, g;        // g: cotangent of the product, (rows_d, NK·U)
  at::Tensor da, db, dw;        // second order only: cotangents of (ga, gb, gw)
  at::Tensor source;
  at::Tensor order, rowptr;     // CSR by target
  at::Tensor ga_edge, gb, gw;   // (E, NA·U) per-edge node-operand adjoint, (E, NB), (E, NP·U)
  at::Tensor grad_g;            // second order only: (splits, rows_d, NK·U) partials
  at::ArrayRef<double> coefficients;
  int64_t channels;
  bool second;
  int64_t splits;
};

template <typename T, int NT>
Coefficients<T, NT> pack(at::ArrayRef<double> values) {
  TORCH_CHECK(values.size() == size_t(NT), "coefficient table has ", values.size(),
              " entries; this (L1, L2) configuration has ", NT, " terms");
  Coefficients<T, NT> c;
  for (int t = 0; t < NT; ++t) c.c[t] = T(values[t]);
  return c;
}

template <typename T, int L1, int L2, int U>
void launch_product(const ProductArgs& x) {
  using Cfg = Config<L1, L2>;
  const auto coef = pack<T, Cfg::NT>(x.coefficients);
  const int64_t rows = x.out.size(1), edges = x.source.numel();
  if (rows == 0) return;
  TORCH_CHECK(rows <= std::numeric_limits<int>::max(), "too many rows for one grid");
  product_kernel<T, L1, L2, U>
      <<<dim3(unsigned(rows), unsigned(x.splits)), U, 0, at::cuda::getCurrentCUDAStream()>>>(
      x.a.const_data_ptr<T>(), x.b.const_data_ptr<T>(), x.w.const_data_ptr<T>(),
      x.source.const_data_ptr<int64_t>(), x.order.const_data_ptr<int32_t>(),
      x.rowptr.const_data_ptr<int32_t>(), x.out.mutable_data_ptr<T>(), x.a.size(0), edges,
      x.channels, coef);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

template <typename T, int L1, int L2, int U, bool Second, int Part>
void launch_adjoint_part(const AdjointArgs& x, const Coefficients<T, Config<L1, L2>::NT>& coef) {
  const int64_t rows = x.g.size(0), edges = x.source.numel();
  adjoint_kernel<T, L1, L2, U, Second, Part>
      <<<dim3(unsigned(rows), unsigned(x.splits)), U, 0, at::cuda::getCurrentCUDAStream()>>>(
      x.a.const_data_ptr<T>(), x.b.const_data_ptr<T>(), x.w.const_data_ptr<T>(),
      x.g.const_data_ptr<T>(), Second ? x.da.const_data_ptr<T>() : nullptr,
      Second ? x.db.const_data_ptr<T>() : nullptr, Second ? x.dw.const_data_ptr<T>() : nullptr,
      x.source.const_data_ptr<int64_t>(), x.order.const_data_ptr<int32_t>(),
      x.rowptr.const_data_ptr<int32_t>(), x.ga_edge.mutable_data_ptr<T>(),
      x.gb.mutable_data_ptr<T>(), x.gw.mutable_data_ptr<T>(),
      Second ? x.grad_g.mutable_data_ptr<T>() : nullptr, x.a.size(0), edges, x.channels, coef);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

template <typename T, int L1, int L2, int U>
void launch_adjoint(const AdjointArgs& x) {
  using Cfg = Config<L1, L2>;
  const auto coef = pack<T, Cfg::NT>(x.coefficients);
  if (x.g.size(0) == 0) return;
  TORCH_CHECK(x.g.size(0) <= std::numeric_limits<int>::max(), "too many rows for one grid");
  if (!x.second) {
    launch_adjoint_part<T, L1, L2, U, false, 0>(x, coef);
  } else if constexpr (sizeof(T) == 4) {
    launch_adjoint_part<T, L1, L2, U, true, 0>(x, coef);
  } else {
    // Double: the second order's operands and accumulators exceed one
    // register file; grad_g and the edge adjoints in two passes.
    launch_adjoint_part<T, L1, L2, U, true, 1>(x, coef);
    launch_adjoint_part<T, L1, L2, U, true, 2>(x, coef);
  }
}

template <int L1, int L2>
void run_product(const ProductArgs& x) {
  AT_DISPATCH_FLOATING_TYPES(x.out.scalar_type(), "channelwise_product", [&] {
    switch (x.channels) {
      case 8: launch_product<scalar_t, L1, L2, 8>(x); break;
      case 16: launch_product<scalar_t, L1, L2, 16>(x); break;
      case 32: launch_product<scalar_t, L1, L2, 32>(x); break;
      case 64: launch_product<scalar_t, L1, L2, 64>(x); break;
      case 128: launch_product<scalar_t, L1, L2, 128>(x); break;
      default:
        // Wider rows: 128-thread CTAs in channel tiles.
        TORCH_CHECK(x.channels % 128 == 0, "unsupported channel multiplicity ", x.channels);
        launch_product<scalar_t, L1, L2, 128>(x);
    }
  });
}

template <int L1, int L2>
void run_adjoint(const AdjointArgs& x) {
  AT_DISPATCH_FLOATING_TYPES(x.a.scalar_type(), "channelwise_adjoint", [&] {
    switch (x.channels) {
      case 8: launch_adjoint<scalar_t, L1, L2, 8>(x); break;
      case 16: launch_adjoint<scalar_t, L1, L2, 16>(x); break;
      case 32: launch_adjoint<scalar_t, L1, L2, 32>(x); break;
      case 64: launch_adjoint<scalar_t, L1, L2, 64>(x); break;
      case 128: launch_adjoint<scalar_t, L1, L2, 128>(x); break;
      default:
        // Wider rows: 128-thread CTAs in channel tiles.
        TORCH_CHECK(x.channels % 128 == 0, "unsupported channel multiplicity ", x.channels);
        launch_adjoint<scalar_t, L1, L2, 128>(x);
    }
  });
}

// Explicit instantiations: one translation unit per (L1, L2). L2 = 1 serves
// the tiny l_max = 1 models of the test tier; production MACE is L2 = 3.
#define MOLNEX_EQUIVARIANCE_CONFIGS(X) \
  X(0, 1) X(1, 1) X(0, 2) X(1, 2) X(2, 2) X(3, 2) X(0, 3) X(1, 3) X(2, 3) X(3, 3)
#define MOLNEX_EQUIVARIANCE_DECLARE(L1, L2)                     \
  extern template void run_product<L1, L2>(const ProductArgs&); \
  extern template void run_adjoint<L1, L2>(const AdjointArgs&);
MOLNEX_EQUIVARIANCE_CONFIGS(MOLNEX_EQUIVARIANCE_DECLARE)
#undef MOLNEX_EQUIVARIANCE_DECLARE

}  // namespace molnex::equivariance
